</script>
<template><div class="drawer-backdrop" @click.self="emit('close')"><aside class="detail-drawer"><div class="drawer-head"><div><span class="eyebrow">TASK DETAIL</span><h2>{{ task?.id }}</h2><p>{{ task?.project }} · {{ task?.area }}</p></div><button class="close-button" @click="emit('close')"><X :size="18"/></button></div><div class="detail-content"><div class="task-status-head"><StatusBadge :status="task?.status"/><span>执行人：{{ task?.pilot }} · {{ task?.drone }}</span></div><div class="detail-section"><h3>任务包</h3><div class="detail-grid"><div><span>巡检区域</span><b>{{ task?.regionCode }}</b></div><div><span>计划时间</span><b>{{ task?.date }}</b></div><div><span>照片</span><b>{{ task?.files?.photo }} 张</b></div><div><span>视频 / 飞行记录</span><b>{{ task?.files?.video }} 段 / {{ task?.files?.flight }} 条</b></div></div><p class="task-note">{{ task?.note }}</p></div><div class="detail-section"><h3>飞手移动端操作</h3><p class="section-help">模拟“我的任务 → 外业执行 → 上传资料 → 完整性校验 → 提交任务”的移动端流程。</p><div class="drawer-actions"><button v-if="task?.status === '待执行' || task?.status === '已暂停'" class="btn-primary" @click="emit('start')"><Play :size="14"/>开始执行</button><button v-if="task?.status === '执行中'" class="btn-secondary" @click="emit('pause')"><Pause :size="14"/>暂停</button><button v-if="task?.status === '执行中'" class="btn-secondary" @click="emit('complete')"><CheckCircle2 :size="14"/>完成采集</button><button v-if="['执行中','资料待校验'].includes(task?.status)" class="btn-secondary" @click="emit('upload')"><Upload :size="14"/>上传资料</button><button v-if="task?.status === '资料待校验'" class="btn-primary" @click="emit('submit')"><Send :size="14"/>校验并提交</button><button v-if="task?.status === '待AI分析'" class="btn-primary" @click="emit('run-ai')"><BrainCircuit :size="14"/>进入AI分析</button></div></div><div class="detail-section"><h3>处理记录</h3><div v-for="log in logs.slice(0, 5)" :key="log.time + log.text" class="timeline-row"><i></i><span><b>{{ log.text }}</b><small>{{ log.time }} · {{ log.role }}</small></span></div></div></div></asi